-- PostgreSQL schema for the application path. This intentionally does not alter src/lib/db.ts.
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'STUDENT', status TEXT NOT NULL DEFAULT 'ACTIVE', campus_id TEXT, user_type TEXT NOT NULL DEFAULT 'TEACHER_LEARNER', email_verified BOOLEAN NOT NULL DEFAULT FALSE, verification_token TEXT, verification_token_expires TIMESTAMPTZ, is_academic_email BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, user_id TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, display_name TEXT NOT NULL, avatar TEXT, bio TEXT, college TEXT, major TEXT, year TEXT, is_verified_student BOOLEAN NOT NULL DEFAULT FALSE, trust_score DOUBLE PRECISION NOT NULL DEFAULT 70.0, completion_rate DOUBLE PRECISION NOT NULL DEFAULT 100.0, cancellation_rate DOUBLE PRECISION NOT NULL DEFAULT 0.0, hourly_rate_credits INTEGER NOT NULL DEFAULT 1, teaching_style TEXT DEFAULT 'Interactive & Hands-on', languages TEXT DEFAULT 'English', teaching_preference TEXT DEFAULT 'Anyone', profile_visibility TEXT DEFAULT 'PUBLIC', skill_visibility TEXT DEFAULT 'PUBLIC', availability_visibility TEXT DEFAULT 'PUBLIC', portfolio_visibility TEXT DEFAULT 'PUBLIC', learning_goal_visibility TEXT DEFAULT 'PUBLIC', daily_session_limit INTEGER DEFAULT 3, portfolio_url TEXT, ml_consent BOOLEAN NOT NULL DEFAULT TRUE, email_notifications_enabled BOOLEAN DEFAULT TRUE, push_notifications_enabled BOOLEAN DEFAULT TRUE, in_app_notifications_enabled BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skills (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL, category TEXT NOT NULL, icon TEXT DEFAULT 'BookOpen', description TEXT, is_verified BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_skills (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, proficiency TEXT NOT NULL, experience_years DOUBLE PRECISION DEFAULT 1.0, teaching_style TEXT DEFAULT 'Hands-on project based', verification_status TEXT NOT NULL DEFAULT 'CLAIMED', evidence_url TEXT, assessment_score DOUBLE PRECISION, verified_at TIMESTAMPTZ, verified_by TEXT, reassessment_required BOOLEAN DEFAULT FALSE, teaching_days TEXT DEFAULT '["Monday","Wednesday","Friday"]', available_start_time TEXT DEFAULT '17:00', available_end_time TEXT DEFAULT '20:00', preferred_start_time TEXT DEFAULT '18:00', preferred_end_time TEXT DEFAULT '20:00', session_duration_minutes INTEGER DEFAULT 60, timezone TEXT DEFAULT 'Asia/Kolkata', is_flexible BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, skill_id));
CREATE TABLE IF NOT EXISTS learning_goals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, target_proficiency TEXT NOT NULL DEFAULT 'Intermediate', priority TEXT NOT NULL DEFAULT 'MEDIUM', notes TEXT, learning_days TEXT DEFAULT '["Tuesday","Thursday","Saturday"]', available_start_time TEXT DEFAULT '18:00', available_end_time TEXT DEFAULT '21:00', preferred_start_time TEXT DEFAULT '19:00', preferred_end_time TEXT DEFAULT '21:00', session_duration_minutes INTEGER DEFAULT 60, timezone TEXT DEFAULT 'Asia/Kolkata', is_flexible BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, skill_id));
CREATE TABLE IF NOT EXISTS availability_slots (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day_of_week TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC', buffer_minutes INTEGER DEFAULT 15, is_preferred BOOLEAN DEFAULT FALSE, skill_id TEXT REFERENCES skills(id), window_label TEXT DEFAULT 'General', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, title TEXT NOT NULL, skill_id TEXT NOT NULL REFERENCES skills(id), teacher_id TEXT NOT NULL REFERENCES users(id), learner_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'REQUESTED', scheduled_start TIMESTAMPTZ NOT NULL, scheduled_end TIMESTAMPTZ NOT NULL, duration_hours DOUBLE PRECISION NOT NULL DEFAULT 1.0, credits_amount INTEGER NOT NULL DEFAULT 1, mode TEXT NOT NULL DEFAULT 'ONLINE', location_or_url TEXT DEFAULT 'https://meet.skillswap.internal/room', learner_confirmed BOOLEAN NOT NULL DEFAULT FALSE, teacher_confirmed BOOLEAN NOT NULL DEFAULT FALSE, idempotency_key TEXT UNIQUE NOT NULL, notes TEXT, cancellation_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS session_participants (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_role TEXT NOT NULL, confirmed BOOLEAN NOT NULL DEFAULT FALSE, joined_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id,user_id));
CREATE TABLE IF NOT EXISTS session_exchange_agreements (id TEXT PRIMARY KEY, session_id TEXT UNIQUE NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, mentor_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, learner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, taught_skill_id TEXT NOT NULL REFERENCES skills(id), requested_return_skill_id TEXT REFERENCES skills(id), requested_return_skill_name TEXT NOT NULL, return_type TEXT NOT NULL DEFAULT 'SKILL', credit_amount INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'PROPOSED', proposal_count INTEGER NOT NULL DEFAULT 1, proposed_by TEXT NOT NULL, accepted_by TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, accepted_at TIMESTAMPTZ, expires_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS skill_credit_accounts (id TEXT PRIMARY KEY, user_id TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, balance INTEGER NOT NULL DEFAULT 3, escrow_balance INTEGER NOT NULL DEFAULT 0, lifetime_earned INTEGER NOT NULL DEFAULT 0, lifetime_spent INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS credit_transactions (id TEXT PRIMARY KEY, reference_session_id TEXT REFERENCES sessions(id), sender_id TEXT REFERENCES users(id), receiver_id TEXT REFERENCES users(id), amount INTEGER NOT NULL, transaction_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'SETTLED', idempotency_key TEXT UNIQUE NOT NULL, on_chain_tx_hash TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ratings (id TEXT PRIMARY KEY, session_id TEXT UNIQUE NOT NULL REFERENCES sessions(id), rater_id TEXT NOT NULL REFERENCES users(id), ratee_id TEXT NOT NULL REFERENCES users(id), score DOUBLE PRECISION NOT NULL CHECK(score BETWEEN 1 AND 5), review TEXT, skills_demonstrated TEXT, punctuality_score DOUBLE PRECISION DEFAULT 5.0, clarity_score DOUBLE PRECISION DEFAULT 5.0, flagged_suspicious BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reputations (id TEXT PRIMARY KEY, user_id TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, total_reviews INTEGER NOT NULL DEFAULT 0, total_sessions_taught INTEGER NOT NULL DEFAULT 0, total_sessions_learned INTEGER NOT NULL DEFAULT 0, bayesian_rating DOUBLE PRECISION NOT NULL DEFAULT 4.5, reliability_score DOUBLE PRECISION NOT NULL DEFAULT 95.0, teaching_score DOUBLE PRECISION NOT NULL DEFAULT 90.0, reciprocal_rating_ratio DOUBLE PRECISION NOT NULL DEFAULT 0.0, badge_level TEXT DEFAULT 'BRONZE', updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS credentials (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, badge_type TEXT NOT NULL, skill_id TEXT REFERENCES skills(id), token_id TEXT, tx_hash TEXT, criteria_met TEXT NOT NULL, is_revoked BOOLEAN NOT NULL DEFAULT FALSE, issued_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS campus_verifications (id TEXT PRIMARY KEY, user_id TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, student_email TEXT NOT NULL, college_id_card_url TEXT, status TEXT NOT NULL DEFAULT 'PENDING', verified_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id), reported_id TEXT NOT NULL REFERENCES users(id), session_id TEXT REFERENCES sessions(id), reason TEXT NOT NULL, details TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', resolution_notes TEXT, moderator_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS disputes (id TEXT PRIMARY KEY, session_id TEXT UNIQUE NOT NULL REFERENCES sessions(id), initiator_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', evidence_url TEXT, moderator_id TEXT, resolution_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fraud_alerts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), risk_score DOUBLE PRECISION NOT NULL, risk_level TEXT NOT NULL, anomaly_reasons TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING_REVIEW', reviewed_by TEXT, review_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, previous_state TEXT, new_state TEXT, ip_address TEXT, user_agent TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, message TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'INFO', related_entity_type TEXT, related_entity_id TEXT, action_url TEXT, link TEXT, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, read_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS notification_preferences (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, in_app_enabled BOOLEAN NOT NULL DEFAULT TRUE, email_enabled BOOLEAN NOT NULL DEFAULT TRUE, session_updates BOOLEAN NOT NULL DEFAULT TRUE, mentor_available BOOLEAN NOT NULL DEFAULT TRUE, credits BOOLEAN NOT NULL DEFAULT TRUE, security BOOLEAN NOT NULL DEFAULT TRUE, system BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS session_events (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, actor_id TEXT, event_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT, previous_state TEXT, new_state TEXT, metadata_json TEXT DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wallets (id TEXT PRIMARY KEY, user_id TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, address TEXT UNIQUE NOT NULL, chain_id INTEGER NOT NULL DEFAULT 31337, signature_proof TEXT NOT NULL, is_verified BOOLEAN NOT NULL DEFAULT TRUE, linked_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS blockchain_transactions (id TEXT PRIMARY KEY, reference_type TEXT NOT NULL, reference_id TEXT NOT NULL, chain_id INTEGER NOT NULL, contract_address TEXT NOT NULL, tx_hash TEXT UNIQUE NOT NULL, status TEXT NOT NULL DEFAULT 'CONFIRMED', block_number INTEGER, payload_json TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS study_groups (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, subject TEXT NOT NULL, creator_id TEXT NOT NULL REFERENCES users(id), meeting_schedule TEXT DEFAULT 'Every Wednesday 5 PM', max_members INTEGER NOT NULL DEFAULT 8, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS study_group_members (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES study_groups(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'MEMBER', joined_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(group_id,user_id));
CREATE TABLE IF NOT EXISTS study_resources (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, subject TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES users(id), resource_type TEXT NOT NULL DEFAULT 'PDF', file_url TEXT, upvotes INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS flashcard_decks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, subject TEXT NOT NULL, cards_count INTEGER NOT NULL DEFAULT 0, is_public BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS flashcards (id TEXT PRIMARY KEY, deck_id TEXT NOT NULL REFERENCES flashcard_decks(id) ON DELETE CASCADE, front TEXT NOT NULL, back TEXT NOT NULL, mastery_level INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS exchange_proposals (id TEXT PRIMARY KEY, cycle_hash TEXT UNIQUE NOT NULL, participants_json TEXT NOT NULL, skills_flow_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PROPOSED', accepted_users_json TEXT NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS skill_assessments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, score DOUBLE PRECISION NOT NULL, max_score DOUBLE PRECISION NOT NULL, percentage DOUBLE PRECISION NOT NULL, passed BOOLEAN NOT NULL DEFAULT FALSE, target_level TEXT NOT NULL DEFAULT 'Beginner', verified_level TEXT, version TEXT NOT NULL DEFAULT 'v1.0', answers_json TEXT, attempts INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skill_evidence (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, evidence_type TEXT NOT NULL, title TEXT NOT NULL, url TEXT, description TEXT, status TEXT NOT NULL DEFAULT 'PENDING', reviewed_by TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skill_requests (id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, requested_proficiency TEXT NOT NULL DEFAULT 'Beginner', current_proficiency TEXT NOT NULL DEFAULT 'Beginner', learning_goal TEXT, preferred_schedule TEXT, preferred_session_mode TEXT NOT NULL DEFAULT 'ONLINE', urgency TEXT NOT NULL DEFAULT 'MEDIUM', status TEXT NOT NULL DEFAULT 'OPEN', matched_teacher_id TEXT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_requests (id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id), skill_name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Computer Science', requested_proficiency TEXT NOT NULL DEFAULT 'Beginner', preferred_days TEXT NOT NULL DEFAULT '["Tuesday","Thursday"]', preferred_time_start TEXT NOT NULL DEFAULT '17:00', preferred_time_end TEXT NOT NULL DEFAULT '20:00', duration_hours DOUBLE PRECISION NOT NULL DEFAULT 1.0, learning_goal TEXT, search_scope TEXT NOT NULL DEFAULT 'ALL', status TEXT NOT NULL DEFAULT 'OPEN', matched_mentor_id TEXT REFERENCES users(id), matched_at TIMESTAMPTZ, match_score DOUBLE PRECISION, match_reasons_json TEXT DEFAULT '[]', session_id TEXT REFERENCES sessions(id), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS learning_request_matches (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES learning_requests(id) ON DELETE CASCADE, mentor_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, match_score DOUBLE PRECISION NOT NULL, match_reasons_json TEXT NOT NULL DEFAULT '[]', notified_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'FOUND', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(request_id,mentor_id));
CREATE TABLE IF NOT EXISTS learning_request_events (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES learning_requests(id) ON DELETE CASCADE, event_type TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, metadata_json TEXT DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_deliveries (id TEXT PRIMARY KEY, notification_id TEXT, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, request_id TEXT, type TEXT NOT NULL DEFAULT 'MENTOR_FOUND', channel TEXT NOT NULL DEFAULT 'IN_APP', recipient TEXT, subject TEXT, content TEXT, status TEXT NOT NULL DEFAULT 'SENT', error_details TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at TIMESTAMPTZ, delivered_at TIMESTAMPTZ, read_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS session_attendance (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_type TEXT NOT NULL, joined_at TIMESTAMPTZ, left_at TIMESTAMPTZ, duration_seconds INTEGER DEFAULT 0, metadata_json TEXT DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chat_messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'SENT', is_system BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS session_signaling_messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, receiver_id TEXT, signal_type TEXT NOT NULL, payload_json TEXT NOT NULL, is_consumed BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS session_room_presence (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, display_name TEXT NOT NULL, role TEXT NOT NULL, camera_on BOOLEAN NOT NULL DEFAULT TRUE, mic_on BOOLEAN NOT NULL DEFAULT TRUE, screen_sharing BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL DEFAULT 'CONNECTED', last_ping TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id,user_id));
CREATE TABLE IF NOT EXISTS session_scratchpads (id TEXT PRIMARY KEY, session_id TEXT UNIQUE NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, content TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'javascript', updated_by TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skill_subscriptions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, skill_id TEXT NOT NULL REFERENCES skills(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,skill_id));
CREATE TABLE IF NOT EXISTS study_roadmaps (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, goal TEXT NOT NULL, current_level TEXT NOT NULL DEFAULT 'Beginner', target_level TEXT NOT NULL DEFAULT 'Intermediate', weekly_hours INTEGER DEFAULT 6, estimated_duration TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roadmap_stages (id TEXT PRIMARY KEY, roadmap_id TEXT NOT NULL REFERENCES study_roadmaps(id) ON DELETE CASCADE, stage_order INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, skill_query TEXT NOT NULL, estimated_hours INTEGER DEFAULT 5, objectives_json TEXT NOT NULL DEFAULT '[]', practice_tasks_json TEXT NOT NULL DEFAULT '[]', completion_criteria_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'NOT_STARTED', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email); CREATE INDEX IF NOT EXISTS idx_profiles_user_id ON profiles(user_id); CREATE INDEX IF NOT EXISTS idx_user_skills_user ON user_skills(user_id); CREATE INDEX IF NOT EXISTS idx_user_skills_skill ON user_skills(skill_id); CREATE INDEX IF NOT EXISTS idx_learning_goals_user ON learning_goals(user_id); CREATE INDEX IF NOT EXISTS idx_availability_user ON availability_slots(user_id); CREATE INDEX IF NOT EXISTS idx_sessions_teacher ON sessions(teacher_id); CREATE INDEX IF NOT EXISTS idx_sessions_learner ON sessions(learner_id); CREATE INDEX IF NOT EXISTS idx_sessions_status ON sessions(status); CREATE INDEX IF NOT EXISTS idx_ratings_rater ON ratings(rater_id); CREATE INDEX IF NOT EXISTS idx_ratings_ratee ON ratings(ratee_id); CREATE INDEX IF NOT EXISTS idx_credit_tx_user ON credit_transactions(sender_id,receiver_id); CREATE INDEX IF NOT EXISTS idx_fraud_alerts_user ON fraud_alerts(user_id); CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id); CREATE INDEX IF NOT EXISTS idx_skill_assessments_user ON skill_assessments(user_id); CREATE INDEX IF NOT EXISTS idx_skill_assessments_skill ON skill_assessments(skill_id); CREATE INDEX IF NOT EXISTS idx_skill_evidence_user ON skill_evidence(user_id); CREATE INDEX IF NOT EXISTS idx_skill_requests_skill ON skill_requests(skill_id); CREATE INDEX IF NOT EXISTS idx_skill_requests_learner ON skill_requests(learner_id); CREATE INDEX IF NOT EXISTS idx_learning_requests_learner ON learning_requests(learner_id); CREATE INDEX IF NOT EXISTS idx_learning_requests_skill ON learning_requests(skill_id); CREATE INDEX IF NOT EXISTS idx_learning_requests_status ON learning_requests(status); CREATE INDEX IF NOT EXISTS idx_learning_req_matches_req ON learning_request_matches(request_id); CREATE INDEX IF NOT EXISTS idx_learning_req_events_req ON learning_request_events(request_id); CREATE INDEX IF NOT EXISTS idx_notif_deliveries_user ON notification_deliveries(user_id); CREATE INDEX IF NOT EXISTS idx_session_attendance_sess ON session_attendance(session_id); CREATE INDEX IF NOT EXISTS idx_chat_messages_sess ON chat_messages(session_id); CREATE INDEX IF NOT EXISTS idx_skill_subs_user_skill ON skill_subscriptions(user_id,skill_id); CREATE INDEX IF NOT EXISTS idx_study_roadmaps_user ON study_roadmaps(user_id); CREATE INDEX IF NOT EXISTS idx_roadmap_stages_roadmap ON roadmap_stages(roadmap_id); CREATE INDEX IF NOT EXISTS idx_exchange_session ON session_exchange_agreements(session_id); CREATE INDEX IF NOT EXISTS idx_exchange_mentor ON session_exchange_agreements(mentor_id); CREATE INDEX IF NOT EXISTS idx_exchange_learner ON session_exchange_agreements(learner_id); CREATE INDEX IF NOT EXISTS idx_session_participants_session ON session_participants(session_id); CREATE INDEX IF NOT EXISTS idx_session_participants_user ON session_participants(user_id,session_role); CREATE INDEX IF NOT EXISTS idx_sessions_sched_start ON sessions(scheduled_start); CREATE INDEX IF NOT EXISTS idx_credit_tx_date ON credit_transactions(created_at); CREATE INDEX IF NOT EXISTS idx_credit_tx_ref_session ON credit_transactions(reference_session_id);